<div class="page-head"><div><h1>Platform messages</h1><p class="muted">Contact form on the platform website.</p></div></div>
<div class="msg-list"><?php foreach ($messages as $m): ?><article class="card msg<?= $m['read_at'] ? '' : ' is-unread' ?>"><header><strong><?= e($m['name']) ?></strong> <a href="mailto:<?= e($m['email']) ?>"><?= e($m['email']) ?></a> <?= e($m['phone']) ?> <span class="muted small"><?= e(fmt_date($m['created_at'], true)) ?></span><?php if ($m['subject']): ?> · <em><?= e($m['subject']) ?></em><?php endif ?></header><p><?= nl2br(e($m['message'])) ?></p><form method="post" class="inline"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) $m['id'] ?>"><?php if (!$m['read_at']): ?><button class="btn btn-xs btn-ghost" name="act" value="read">Mark read</button><?php endif ?> <button class="btn btn-xs btn-link" name="act" value="delete" data-confirm="Delete?">Delete</button></form></article><?php endforeach ?>
<?php if (!$messages): ?><p class="muted">No messages.</p><?php endif ?></div>
